-- modules/aman/recommendations_schema.sql
-- ==========================================
-- PostgreSQL-compatible schema for the Recommendations table.
--
-- IMPORTANT: Run SHOW TABLES (or \dt in psql) before executing this script to
-- confirm that no shared Recommendations table already exists.  IF NOT EXISTS
-- prevents a duplicate *name*, but it does NOT guarantee column compatibility
-- with a pre-existing table.
--
-- Primary key  : UUID generated by the application layer (uuid4).
-- file_path    : Free-form text identifier; no FK constraint assumed because
--                the shared Files table schema has not been verified yet.
--                Add a FK once the shared table structure is confirmed.

CREATE TABLE IF NOT EXISTS Recommendations (
    recommendation_id   UUID          PRIMARY KEY,
    file_path           TEXT          NOT NULL,
    recommendation_type VARCHAR(50)   NOT NULL,
    suggested_action    VARCHAR(100)  NOT NULL,
    destination         TEXT,                          -- NULL when no suitable destination exists
    reason              TEXT          NOT NULL,
    priority            VARCHAR(10)   NOT NULL
                            CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH')),
    status              VARCHAR(20)   NOT NULL DEFAULT 'PENDING'
                            CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'COMPLETED')),
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for common query patterns
CREATE INDEX IF NOT EXISTS idx_recommendations_status
    ON Recommendations (status);

CREATE INDEX IF NOT EXISTS idx_recommendations_type
    ON Recommendations (recommendation_type);

CREATE INDEX IF NOT EXISTS idx_recommendations_file_path
    ON Recommendations (file_path);

CREATE INDEX IF NOT EXISTS idx_recommendations_created_at
    ON Recommendations (created_at DESC);

-- -------------------------------------------------------------------------
-- Optional: trigger to auto-update updated_at on row modification (PostgreSQL)
-- -------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION update_recommendations_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_recommendations_updated_at ON Recommendations;

CREATE TRIGGER trg_recommendations_updated_at
BEFORE UPDATE ON Recommendations
FOR EACH ROW
EXECUTE FUNCTION update_recommendations_updated_at();
